// 三种真实来源按Common序和全局分配序双核；实领只授知情，接受才授收件者自己的赴约承诺。
#include "visit_appointment_detail.hpp"
#include "visit_appointment_authored.hpp"
#include "visit_appointment_life.hpp"
#include <set>
namespace hanmo::resident {namespace {
using Positions=std::map<StableId,std::size_t>;
Status earlier(const CommonStore& c,const Positions& positions,const StableId& a,const StableId& kind,Integer tick,const StableId& b,const StableId& bkind,Integer btick){const auto* h=c.state().facts.find(a);const auto x=visit_appointment_detail::serial(a,kind,c.state().next_instance_id),y=visit_appointment_detail::serial(b,bkind,c.state().next_instance_id);const auto ap=positions.find(a),bp=positions.find(b);if(!h||h->id!=a||h->kind!=kind||!x||!y||*x>=*y||ap==positions.end()||bp==positions.end()||ap->second>=bp->second||tick<0||tick>btick)return common_failure("VisitAppointmentSourceOrderMismatch",a);return common_success();}
Status alive(const CommonStore& c,const CommonCatalog& catalog,const VisitAppointmentHistoricalSources& sources,const StableId& actor,Integer tick,const StableId& fact){Outcome<ActorPresenceRead> read;if(sources.people){if(!sources.people->bound_to(c))return common_failure("VisitAppointmentPeopleCandidateMismatch",fact,ErrorKind::internal);const auto*h=c.state().facts.find(fact);if(!h||h->id!=fact)return common_failure("VisitAppointmentPresenceCutMissing",fact,ErrorKind::internal);read=sources.people->read_presence_before_original_fact(actor,tick,{h->domain,h->kind,h->id});}else read=read_actor_presence_before_fact(c,catalog,sources.deaths,actor,tick,fact);return !read.ok?Status{false,{},read.error}:read.value.alive?common_success():common_failure("VisitAppointmentHistoricalActorUnavailable",fact);}
Status contact(const CommonStore& c,const CommonCatalog& common,const InteractionCatalog& definitions,const VisitAppointmentHistoricalSources& sources,Integer current_tick,const VisitMessagePolicy& p,const VisitMessageContact& v,const StableId& actor,const StableId& node,const StableId& fact,const StableId& kind){const auto* role=definitions.common->roles.find(p.role_id);const auto a=visit_appointment_detail::serial(fact,kind,c.state().next_instance_id),s=visit_appointment_detail::serial(v.session_id,"interaction",c.state().next_instance_id);if(!role||v.actor_id!=actor||v.custodian_actor_id!=p.custodian_actor_id||v.place_id!=role->place_id||v.role_id!=p.role_id||v.dialogue_id!=p.dialogue_id||v.node_id!=node||v.tick<0||v.tick>current_tick||!a||!s||*s>=*a)return common_failure("InvalidVisitAppointmentContact",fact);for(const auto& person:{actor,v.custodian_actor_id}){auto valid=alive(c,common,sources,person,v.tick,fact);if(!valid.ok)return valid;}return common_success();}

}
Status validate_visit_appointment_original_sources(const CommonStore& c,const CommonCatalog& common,const VisitMessageState& messages,const VisitMessageCatalog& originals,const PersonalAppointmentCatalog& appointments,const PersonalAppointmentState& old,const InteractionCatalog& definitions,const VisitAppointmentCatalog& catalog,const VisitAppointmentState& state,const VisitAppointmentHistoricalSources& sources,const VisitReplyCatalog* ordinary){
 Integer current_tick=c.tick();if(state.version==2){if(!sources.clock||!sources.people||!sources.life)return common_failure("VisitAppointmentLifeHistoryRequired",{},ErrorKind::unsupported_capability);if(&sources.life->common!=&c||&sources.life->state!=&state||&sources.life->people!=sources.people||&sources.life->clock!=sources.clock)return common_failure("VisitAppointmentHistoricalCandidateMismatch",{},ErrorKind::internal);auto now=sources.clock->read_current_moment();if(!now.ok)return {false,{},now.error};current_tick=now.value.half_day_tick;}auto valid=validate_visit_messages(c,messages,originals,definitions,sources.clock);if(!valid.ok)return valid;valid=validate_visit_appointment_catalog(catalog,originals,appointments,definitions,ordinary);if(!valid.ok)return valid;if((state.version!=1&&state.version!=2)||state.version!=catalog.version||(state.version==1&&!state.life_sources.empty())||state.offered.size()>65536||state.collected.size()>65536||state.accepted.size()>65536)return common_failure("InvalidVisitAppointmentState");Positions positions;std::size_t position=0;for(const auto& row:c.state().facts.rows())positions.emplace(row.first,position++);std::vector<StableId> offers,collections,acceptances;std::set<StableId> answered,delivered,agreed;Integer last_id=0,last_tick=-1;
 for(const auto& row:c.state().facts.rows()){const auto& h=row.second;const bool offering=h.kind==visit_appointment_offered_kind,collecting=h.kind==visit_appointment_collected_kind,accepting=h.kind==visit_appointment_accepted_kind;if(!offering&&!collecting&&!accepting){if(h.domain==visit_appointment_module)return common_failure("UnknownVisitAppointmentFact",row.first);continue;}const auto id=visit_appointment_detail::serial(row.first,h.kind,c.state().next_instance_id);if(h.id!=row.first||h.domain!=visit_appointment_module||!id||*id<=last_id)return common_failure("InvalidVisitAppointmentFact",row.first);last_id=*id;StableId actor;Integer tick=-1;bool authored=false;
  if(offering){const auto* offer=state.offered.find(row.first);const auto* p=offer?visit_appointment_policy(catalog,offer->policy_id):nullptr;const auto* m=p?visit_appointment_detail::original(originals,p->message_policy_id):nullptr;const auto* a=p?personal_appointment_policy(appointments,p->appointment_policy_id):nullptr;const auto* message=offer?messages.posted.find(offer->message_fact_id):nullptr;const auto* received=offer?messages.received.find(offer->received_fact_id):nullptr;if(!offer||offer->fact_id!=row.first||!p||!m||!a||!message||message->policy_id!=m->id||!received||received->message_fact_id!=message->fact_id||received->contact.actor_id!=m->recipient_actor_id||!answered.insert(message->fact_id).second)return common_failure("InvalidVisitAppointmentOfferSource",row.first);
   // 永久claim只证会话来源；当时是否NPC仍由原控制链逐本次业务头独立证明。
   authored=bool(offer->authored_origin);auto expected=visit_appointment_detail::terms(*p,*m,*a,definitions,offer->contact.tick);if(!expected.ok)return {false,{},expected.error};if(!visit_appointment_detail::same_terms(expected.value,offer->terms))return common_failure("VisitAppointmentTermsChanged",row.first);
   valid=earlier(c,positions,message->fact_id,visit_message_posted_kind,message->contact.tick,received->fact_id,visit_message_received_kind,received->contact.tick);if(!valid.ok)return valid;valid=earlier(c,positions,received->fact_id,visit_message_received_kind,received->contact.tick,row.first,h.kind,offer->contact.tick);if(!valid.ok)return valid;for(const auto* original_contact:{&message->contact,&received->contact})for(const auto& person:{original_contact->actor_id,original_contact->custodian_actor_id}){valid=alive(c,common,sources,person,original_contact->tick,original_contact==&message->contact?message->fact_id:received->fact_id);if(!valid.ok)return valid;}valid=contact(c,common,definitions,sources,current_tick,*m,offer->contact,m->recipient_actor_id,p->offer_node_id,row.first,h.kind);if(!valid.ok)return valid;actor=offer->contact.actor_id;tick=offer->contact.tick;offers.push_back(row.first);
  }else if(collecting){const auto* collection=state.collected.find(row.first);const auto* offer=collection?state.offered.find(collection->invitation_fact_id):nullptr;const auto* p=offer?visit_appointment_policy(catalog,offer->policy_id):nullptr;const auto* m=p?visit_appointment_detail::original(originals,p->message_policy_id):nullptr;if(!collection||collection->fact_id!=row.first||!offer||!m||!answered.count(offer->message_fact_id)||!delivered.insert(offer->fact_id).second)return common_failure("InvalidVisitAppointmentCollectionSource",row.first);valid=earlier(c,positions,offer->fact_id,visit_appointment_offered_kind,offer->contact.tick,row.first,h.kind,collection->contact.tick);if(!valid.ok)return valid;valid=contact(c,common,definitions,sources,current_tick,*m,collection->contact,m->sender_actor_id,p->collect_node_id,row.first,h.kind);if(!valid.ok)return valid;actor=collection->contact.actor_id;tick=collection->contact.tick;collections.push_back(row.first);
  }else{const auto* acceptance=state.accepted.find(row.first);const auto* offer=acceptance?state.offered.find(acceptance->invitation_fact_id):nullptr;const auto* collection=acceptance?state.collected.find(acceptance->collection_fact_id):nullptr;if(!acceptance||acceptance->fact_id!=row.first||!offer||!collection||collection->invitation_fact_id!=offer->fact_id||!delivered.count(offer->fact_id)||!agreed.insert(offer->fact_id).second||acceptance->actor_id!=offer->terms.invitee_actor_id||collection->contact.actor_id!=acceptance->actor_id||acceptance->tick>=offer->terms.accept_before_tick||acceptance->tick>current_tick)return common_failure("InvalidVisitAppointmentAcceptanceSource",row.first);valid=earlier(c,positions,collection->fact_id,visit_appointment_collected_kind,collection->contact.tick,row.first,h.kind,acceptance->tick);if(!valid.ok)return valid;valid=alive(c,common,sources,acceptance->actor_id,acceptance->tick,row.first);if(!valid.ok)return valid;actor=acceptance->actor_id;tick=acceptance->tick;acceptances.push_back(row.first);
  }
  if(tick<last_tick)return common_failure("VisitAppointmentChronologyMismatch",row.first);last_tick=tick;if(!sources.player_before_fact)return common_failure("VisitAppointmentHistoricalPlayerRequired",row.first);auto player=sources.player_before_fact(tick,row.first);if(!player.ok)return {false,{},player.error};if(player.value.empty()||!c.actor(player.value)||(authored?player.value==actor:player.value!=actor))return common_failure("VisitAppointmentHistoricalPlayerMismatch",row.first);
 }
 if(offers!=state.offered.order()||collections!=state.collected.order()||acceptances!=state.accepted.order())return common_failure("VisitAppointmentFactCoverageMismatch");valid=validate_visit_appointment_authored_sources(c,originals,appointments,definitions,catalog,state,sources.authored,ordinary);if(!valid.ok)return valid;return common_success();
}
Status validate_visit_appointments(const CommonStore& c,const CommonCatalog& common,const VisitMessageState& messages,const VisitMessageCatalog& originals,const PersonalAppointmentCatalog& appointments,const PersonalAppointmentState& old,const InteractionCatalog& definitions,const VisitAppointmentCatalog& catalog,const VisitAppointmentState& state,const VisitAppointmentHistoricalSources& sources,const VisitReplyCatalog* ordinary){auto valid=validate_visit_appointment_original_sources(c,common,messages,originals,appointments,old,definitions,catalog,state,sources,ordinary);if(!valid.ok)return valid;return state.version==2?validate_visit_appointment_life_sources(*sources.life):common_success();}

}
